static class RecentStore {
#if TEST_BUILD
 static readonly string path=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","tests","kaiwu-recent-test.json"));
#else
 static readonly string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"GlintPlayer","recent-files.json");
#endif
 internal sealed class Entry {public string File {get;set;}public DateTime Opened {get;set;}}
 internal static List<Entry> Read(){try{return (new JavaScriptSerializer().Deserialize<List<Entry>>(System.IO.File.ReadAllText(path))??new List<Entry>()).Where(x=>System.IO.File.Exists(x.File)).Take(12).ToList();}catch{return new List<Entry>();}}
 internal static void Record(string file){if(!System.IO.File.Exists(file))return;try{file=Path.GetFullPath(file);var list=Read();list.RemoveAll(x=>string.Equals(x.File,file,StringComparison.OrdinalIgnoreCase));list.Insert(0,new Entry{File=file,Opened=DateTime.UtcNow});Directory.CreateDirectory(Path.GetDirectoryName(path));System.IO.File.WriteAllText(path,new JavaScriptSerializer().Serialize(list.Take(12).ToList()));}catch{}}
}
