partial class Player {
 HomeView home;bool homeMode=true;
 void InitializeHome(){home=new HomeView();home.OpenFile=Open;home.OpenDocument=()=>EnterDocuments(null);home.OpenTool=OpenTool;home.DropFiles=LoadFiles;home.Resume=ResumeMedia;Controls.Add(home);home.BringToFront();footer.Visible=false;}
