 void ShowHome(){if(engine==null)return;if(fullscreen)ToggleFullscreen();StopGif();engine.Set("pause","yes");if(documentMode)LeaveDocuments();homeMode=true;SetWindowChrome(false);MinimumSize=new Size(760,520);if(WindowState==FormWindowState.Normal&&(Width<820||Height<620))Size=new Size(1100,730);home.SetResume(loaded);home.Visible=true;home.BringToFront();if(shellBar!=null){shellBar.Active="home";KeepShell();}footer.Visible=false;Text="开物";}
 void ResumeMedia(){homeMode=false;home.Hide();SetWindowChrome(true);MinimumSize=imageMode?new Size(320,260):new Size(540,340);images.Visible=imageMode;video.Visible=!imageMode;footer.Visible=true;if(shellBar!=null){shellBar.Active="media";KeepShell();}if(imageMode)AdjustImageWindow();Text=Path.GetFileName(current)+" · 开物";Touch();}
